        static VisualElement Box(VisualElement parent,string cls){var e=new VisualElement();e.AddToClassList(cls);parent.Add(e);return e;}
        void AddExplorer(VisualElement panel,VisualElement world,VisualElement appearance)
        {
            showMarkers=new Toggle("Coğrafya işaretleri"){value=true};panel.Add(showMarkers);explore=new DropdownField("Biyom ve coğrafya keşfi");panel.Add(explore);Button(panel,"Seçilen bölgeye git ↗",()=>{if(explore.index>=0&&explore.index<placesList.Count)VisitPlace(placesList[explore.index]);});selection=Label(panel,"Bir işarete veya yüzeye tıkla.","muted");Button(panel,"Yüzeye in",()=>app.Visit(selectedDirection.Length>.5?selectedDirection:app.Focus,700));Button(panel,"Geçişi canlandır",()=>app.Routes.Preview());
            markerLayer=Box(world,"map-markers");markerLayer.pickingMode=PickingMode.Ignore;markerLayer.SendToBack();
            var tools=Box(world,"viewport-tools");Button(tools,"Ⅱ",()=>app.pausedSky=!app.pausedSky);Button(tools,"⛶",()=>Screen.fullScreen=!Screen.fullScreen);Button(tools,"◧",()=>{app.clean=!app.clean;SetClean(app.clean);});
            Label(appearance,"GÖRÜNTÜ AYRINTISI","eyebrow");Slider(appearance,"Geometri ekran hatası",1,5,2.5f,x=>app.Terrain.pixelError=x);Button(appearance,"Tam ayrıntı",()=>app.Terrain.pixelError=1);Label(appearance,"1 px: en yoğun geometri · 5 px: daha az geometri\nYakın doku çözünürlüğü korunur.","muted");
        }
        void VisitPlace(Landmark place){app.SelectedFeature=place.id;selectedDirection=new D3(place.direction);app.Visit(selectedDirection,place.rangeMeters);SelectPosition(selectedDirection);}
        public void SelectPosition(D3 direction)
        {selectedDirection=direction;if(app.Kernel==null||selection==null)return;var s=app.Kernel.Sample(direction);selection.text=$"{CoordinatesText(direction)}\nYükselti {Distance(s.height)} · Su {Distance(s.Depth)}\nBiyom {s.biome} · Orman %{s.forest*100:F0}\n{s.feature}";}
        void RebuildExplorer()
        {
            placesList.Clear();markerButtons.Clear();markerPositions.Clear();markerLayer.Clear();var w=app.Kernel.World;foreach(var p in w.landmarks)if(p.direction!=null)placesList.Add(p);foreach(var lake in w.hydrology.lakes)placesList.Add(new Landmark{id=lake.id,name=lake.name??lake.id,direction=lake.direction,rangeMeters=10000});foreach(var crossing in w.crossings)if(crossing.direction!=null)placesList.Add(new Landmark{id=crossing.id,name=crossing.name??crossing.id,direction=crossing.direction,rangeMeters=2000});
            var names=new System.Collections.Generic.List<string>();foreach(var p in placesList){names.Add(p.name??p.id);var markerDirection=new D3(p.direction);markerPositions.Add(markerDirection*(w.radiusMeters+app.Kernel.Sample(markerDirection,false).height+35));var place=p;var marker=Button(markerLayer,p.name??p.id,()=>VisitPlace(place),"map-marker");marker.RegisterCallback<PointerEnterEvent>(_=>app.PointerOverUI=true);marker.RegisterCallback<PointerLeaveEvent>(_=>app.PointerOverUI=false);markerButtons.Add(marker);}explore.choices=names;if(names.Count>0)explore.index=0;
        }
        static Label Label(VisualElement parent,string text,string cls=null){var e=new Label(text);if(cls!=null)e.AddToClassList(cls);parent.Add(e);return e;}
        static Button Button(VisualElement parent,string text,Action action,string cls=null){var b=new Button(action){text=text};if(cls!=null)b.AddToClassList(cls);parent.Add(b);return b;}
        static Slider Slider(VisualElement parent,string name,float lo,float hi,float value,Action<float> change){var e=new Slider(name,lo,hi){value=value,showInputField=true};if(change!=null)e.RegisterValueChangedCallback(v=>change(v.newValue));parent.Add(e);return e;}
        public void SetClean(bool value){clean=value;bar.style.display=clean?DisplayStyle.None:DisplayStyle.Flex;editor.style.display=clean||app.Flying?DisplayStyle.None:DisplayStyle.Flex;flight.style.display=clean||!app.Flying?DisplayStyle.None:DisplayStyle.Flex;}
        public void RefreshMode(){if(editor==null)return;SetClean(clean);}
        public void WorldChanged(){RebuildExplorer();var c=app.Kernel.World.generationConfig;seed.value=c.seed;caption.text=seed.value;root.Q<Label>(className:"world-title").text=c.seed;root.Q<Label>(className:"world-summary").text=(app.Kernel.World.radiusMeters*2/1000).ToString("N0",TR)+" km çap · "+c.worldType;land.SetValueWithoutNotify((float)c.landBalance);mountains.SetValueWithoutNotify((float)c.mountains);plains.SetValueWithoutNotify((float)c.plains);erosion.SetValueWithoutNotify((float)c.erosion);temperature.SetValueWithoutNotify((float)c.temperature);rain.SetValueWithoutNotify((float)c.rainfall);forest.SetValueWithoutNotify((float)c.forestDensity);}
        void Visit(string id,double distance)
        {var w=app.Kernel.World;foreach(var lake in w.hydrology.lakes)if(lake.id==id){app.Visit(new D3(lake.direction),distance);return;}foreach(var river in w.hydrology.rivers)if(river.id==id){app.Visit(river.points[river.points.Length/2].D,distance);return;}}
        void Generate()
        {var c=new PlanetConfig{seed=seed.value,landBalance=land.value,mountains=mountains.value,plains=plains.value,erosion=erosion.value,temperature=temperature.value,rainfall=rain.value,forestDensity=forest.value};string[] types={"terran","terran","terran","terran","desert","volcanic","mars","moon","alien"};c.worldType=types[preset.index];if(preset.index==1)c.landBalance=.72;if(preset.index==2)c.landBalance=.28;if(preset.index==3){c.mountains=.9;c.temperature=15;}app.Generate(c);}
        void Open(){string p=PlanetFileDialog.Open();if(!string.IsNullOrWhiteSpace(p))_=app.Load(p);}
        void Save(){string p=PlanetFileDialog.Save();if(!string.IsNullOrWhiteSpace(p))app.Save(p);}
        public void Tick()
        {
            status.text=app.Status;if(app.Kernel==null)return;var t=app.Terrain;smoothedFrame=Mathf.Lerp(smoothedFrame,Time.unscaledDeltaTime,.15f);double alt=app.CameraPosition.Length-app.Kernel.World.radiusMeters;
            altitude.text=Distance(alt)+"\n"+CoordinatesText(app.Focus);fps.text=$"{1/Math.Max(.001,smoothedFrame):F0} FPS\n{t.visibleTiles} görünür tile · {t.running} worker\nRAM {t.residentBytes/1048576.0:F1} MiB\nMesh {t.meshBytes/1048576.0:F1} MiB\nSon üretim {t.lastBuildMs:F2} ms\nSon aktarım {t.lastUploadMs:F2} ms\nÇap {app.Kernel.World.radiusMeters*2/1000:N0} km";
            if(!app.Flying){for(int i=0;i<markerButtons.Count;i++){var place=placesList[i];D3 d=new D3(place.direction);var p=app.Camera.WorldToScreenPoint(Coordinates.Float(markerPositions[i]-app.Origin));bool visible=showMarkers.value&&p.z>0&&D3.Dot(d,app.CameraPosition.Unit)>app.Kernel.World.radiusMeters/app.CameraPosition.Length-.0001;markerButtons[i].style.display=visible?DisplayStyle.Flex:DisplayStyle.None;if(visible){markerButtons[i].style.left=p.x/Screen.width*root.resolvedStyle.width;markerButtons[i].style.top=(1-p.y/Screen.height)*root.resolvedStyle.height-64;}}}
            if(!app.Flying||app.Flight==null)return;var f=app.Flight;speed.text=(f.speed*3.6).ToString("N0",TR);agl.text=Distance(f.agl);compass.text=$"DENİZ SEVİYESİ / {Distance(f.altitude)}\n\n{CoordinatesText(f.up)}";health.text=$"GÖVDE  {f.health:F0}%";energy.text=$"BOOST  {f.boostEnergy:F0}%";hull.value=(float)f.health;boost.value=(float)f.boostEnergy;message.text=app.Status;
            flightState.text=(f.state=="flying"?"SERBEST UÇUŞ":f.state=="warping"?"WARP YOLCULUĞU":f.state=="landing"?"İNİŞ YARDIMI":f.state=="landed"?"YERDE":f.state=="taking-off"?"KALKIŞ":"GEMİ DEVRE DIŞI")+"   /   "+f.score+" HEDEF";
            modal.style.display=f.paused||f.health==0?DisplayStyle.Flex:DisplayStyle.None;pausedTitle.text=f.health==0?"Gemi devre dışı":"Uçuş duraklatıldı";
            for(int i=0;i<2;i++){double remaining=i==0?(f.state=="warping"?f.warpDuration-f.warpElapsed:f.warpCharge):f.repairRemaining,cooldown=i==0?f.warpCooldown:f.repairCooldown;skillTime[i].text=remaining>0?remaining.ToString("F1",TR):cooldown>0?Math.Ceiling(cooldown).ToString():"";skillButtons[i].SetEnabled(!f.paused&&f.health>0&&remaining==0&&cooldown==0&&(i==0?f.state=="flying":f.health<100));}
            bool warping=f.warpCharge>0||f.state=="warping";warp.style.display=warping?DisplayStyle.Flex:DisplayStyle.None;if(warping){warpPhase.text=f.warpCharge>0?"WARP DALGASI DOLUYOR":f.warpPhase=="accelerating"?"WARP · HIZLANIYOR":f.warpPhase=="decelerating"?"VARIŞ · YAVAŞLIYOR":"SOLUCAN DELİĞİNDE";warpEta.text=(f.warpCharge>0?f.warpCharge:f.warpDuration-f.warpElapsed).ToString("F1",TR)+" sn";warpDistance.text=Distance(f.warpTravel)+" / "+Distance(FlightModel.WarpDistances[f.warpIndex]);for(int i=0;i<5;i++){distanceButtons[i].style.display=f.warpCharge>0?DisplayStyle.Flex:DisplayStyle.None;distanceButtons[i].EnableInClassList("selected",i==f.warpIndex);}}
            for(int i=0;i<6;i++)
            {var enemy=f.enemies[i];D3 delta=enemy.position-f.position;double distance=delta.Length;var p=app.Camera.WorldToScreenPoint(Coordinates.Float(enemy.position-app.Origin));bool visible=enemy.health>0&&distance<6000&&p.z>0;var node=targetLabels[i];node.style.display=visible?DisplayStyle.Flex:DisplayStyle.None;if(visible){node.style.left=p.x/Screen.width*root.resolvedStyle.width-50;node.style.top=(1-p.y/Screen.height)*root.resolvedStyle.height-25;node.Q<Label>(className:"enemy-distance").text=Distance(distance)+" · "+(enemy.mode=="pursue"?"TAKİP":enemy.mode=="return"?"DÖNÜŞ":"DEVRİYE");node.EnableInClassList("locked",f.target==i&&f.lockTime>=.8);}dots[i].style.display=enemy.health>0&&distance<3000?DisplayStyle.Flex:DisplayStyle.None;dots[i].style.left=Length.Percent(50+(float)PM.Clamp(D3.Dot(delta,f.right)/3000*44,-44,44));dots[i].style.top=Length.Percent(50-(float)PM.Clamp(D3.Dot(delta,f.heading)/3000*44,-44,44));}
        }
        static string Distance(double metres)=>Math.Abs(metres)>=1000?(metres/1000).ToString("N1",TR)+" km":metres.ToString("N0",TR)+" m";
        static string CoordinatesText(D3 d)=>$"{Math.Asin(PM.Clamp(d.y,-1,1))*180/Math.PI:F2}° K / {Math.Atan2(d.z,d.x)*180/Math.PI:F2}° D";
    }
}
